package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_verifyCheckSum_TriageGen2Test {

    // Constants assumed from TarUtils implementation context
    private static final int CHKSUM_OFFSET = 148;
    private static final int CHKSUMLEN = 8;

    /**
     * Helper to create a header of a specific size filled with spaces.
     */
    private byte[] createBaseHeader(int size) {
        byte[] header = new byte[size];
        for (int i = 0; i < size; i++) {
            header[i] = ' ';
        }
        return header;
    }





    @Test
    public void testVerifyCheckSum_StoredSumGreaterThanUnsigned() {
        // COMPRESS-177: return storedSum > unsignedSum
        // To get storedSum > unsignedSum, we need a large octal value.
        // Let's set checksum to '777777' (octal)
        // storedSum = 7*8^5 + 7*8^4 + 7*8^3 + 7*8^2 + 7*8^1 + 7 = 262143
        // The checksum bytes are replaced by ' ' (32) in the sum.
        // We need unsignedSum to be less than 262143.
        byte[] header = createBaseHeader(256);
        header[CHKSUM_OFFSET] = '7';
        header[CHKSUM_OFFSET + 1] = '7';
        header[CHKSUM_OFFSET + 2] = '7';
        header[CHKSUM_OFFSET + 3] = '7';
        header[CHKSUM_OFFSET + 4] = '7';
        header[CHKSUM_OFFSET + 5] = '7';

        // unsignedSum = (256-8)*32 + 8*32 = 256 * 32 = 8192.
        // storedSum = 262143.
        // 262143 > 8192 is true.
        assertTrue(TarUtils.verifyCheckSum(header));
    }










}

package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigInteger;
import java.nio.ByteBuffer;
import java.util.*;
import org.apache.commons.compress.archivers.zip.ZipEncoding;
import org.apache.commons.compress.archivers.zip.ZipEncodingHelper;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class TarUtils_verifyCheckSum_TriageGen2Test {

    // Constants assumed from TarUtils implementation context
    private static final int CHKSUM_OFFSET = 148;
    private static final int CHKSUMLEN = 8;

    /**
     * Helper to create a header of a specific size filled with spaces.
     */
    private byte[] createBaseHeader(int size) {
        byte[] header = new byte[size];
        for (int i = 0; i < size; i++) {
            header[i] = ' ';
        }
        return header;
    }







    @Test
    public void testVerifyCheckSum_StoredSumEqualsSigned() {
        // signedSum can be different from unsignedSum if bytes are negative.
        // However, in standard Tar, we use bytes.
        // If we put a byte with value -1 (0xFF).
        // unsignedSum += 255. signedSum += -1.
        // Let's make storedSum = 0.
        // To make 0 == signedSum, we need signedSum to be 0.
        // If header is [0x00], unsignedSum = 0, signedSum = 0, storedSum = 0.
        // But we need to trigger the checksum offset.
        byte[] header = createBaseHeader(200);
        // header[CHKSUM_OFFSET] is ' ', so digits = 0.
        // unsignedSum = 200 * 32 = 6400.
        // signedSum = 200 * 32 = 6400.
        // storedSum = 0.
        // 0 == 6400 (F) || 0 == 6400 (F) || 0 > 6400 (F) -> false.
        assertFalse(TarUtils.verifyCheckSum(header));
    }








}

