        header[CHKSUM_OFFSET + 6] = '7';

        // digits should stop at 6. storedSum = 123456 (octal)
        // unsignedSum = 200 * 32 = 6400
        // 123456 (octal) is 42862 (dec).
        // 42862 > 6400 is true.
        assertTrue(TarUtils.verifyCheckSum(header));
    }






}

